static void twm_cpu_class_init(ObjectClass *oc, const void *data)
{
    DeviceClass *dc = DEVICE_CLASS(oc);
    CPUClass *cc = CPU_CLASS(oc);
    TWMCPUClass *mcc = TWM_CPU_CLASS(oc);
    ResettableClass *rc = RESETTABLE_CLASS(oc);

    device_class_set_parent_realize(dc, twm_cpu_realizefn, &mcc->parent_realize);
    resettable_class_set_parent_phases(rc, NULL, twm_cpu_reset_hold, NULL,
                                       &mcc->parent_phases);
    cc->class_by_name = twm_cpu_class_by_name;
    cc->dump_state = twm_cpu_dump_state;
    cc->set_pc = twm_cpu_set_pc;
    cc->get_pc = twm_cpu_get_pc;
    cc->sysemu_ops = &twm_sysemu_ops;
    cc->tcg_ops = &twm_tcg_ops;
}

